{%- set company = frappe.get_doc('Company', doc.company) -%}
{%- set _general_config_exists = frappe.db.exists("DocType", "DW General Configuration") -%}
{%- set _company_name = (frappe.db.get_single_value("DW General Configuration", "company_name") if _general_config_exists else "") or company.company_name or doc.company -%}
{%- set _company_phone = (frappe.db.get_single_value("DW General Configuration", "company_phone") if _general_config_exists else "") or company.phone_no or "" -%}
{%- set _company_address = (frappe.db.get_single_value("DW General Configuration", "company_address") if _general_config_exists else "") or company.company_address or company.address or "" -%}
{%- set _cr_number = (frappe.db.get_single_value("DW General Configuration", "cr_number") if _general_config_exists else "") or "" -%}
{%- set _vat_registration_number = (frappe.db.get_single_value("DW General Configuration", "vat_registration_number") if _general_config_exists else "") or company.tax_id or "" -%}
{%- set has_pms = doc.dw_has_pms_items -%}
{%- set currency = doc.currency or company.default_currency or 'BHD' -%}
{%- set pms_disclaimer = doc.dw_pms_disclaimer or '' -%}

<style>
  .pms-invoice { font-family: Arial, Helvetica, sans-serif; font-size: 10pt; color: #333; }
  .pms-invoice table { width: 100%; border-collapse: collapse; margin-bottom: 10px; }
  .pms-invoice th { background: #f5f5f5; border: 1px solid #ccc; padding: 6px 8px; text-align: left; font-size: 9pt; }
  .pms-invoice td { border: 1px solid #ccc; padding: 6px 8px; font-size: 9.5pt; }
  .pms-invoice .text-right { text-align: right; }
  .pms-invoice .text-center { text-align: center; }
  .pms-invoice .header-section { margin-bottom: 15px; }
  .pms-invoice .company-name { font-size: 16pt; font-weight: bold; margin-bottom: 2px; }
  .pms-invoice .company-detail { font-size: 8.5pt; color: #666; }
  .pms-invoice .invoice-title { font-size: 13pt; font-weight: bold; text-align: center; margin: 12px 0 8px; text-transform: uppercase; }
  .pms-invoice .meta-table td { border: none; padding: 2px 8px; font-size: 9pt; }
  .pms-invoice .totals-table { width: 50%; margin-left: auto; }
  .pms-invoice .totals-table td { border: none; padding: 3px 8px; }
  .pms-invoice .totals-table .grand-total td { font-weight: bold; font-size: 11pt; border-top: 2px solid #333; }
  .pms-invoice .pms-disclaimer { margin-top: 15px; padding: 8px 12px; border: 1px solid #c00; background: #fff8f8; font-size: 9pt; font-weight: bold; color: #c00; text-align: center; }
  .pms-invoice .footer-note { margin-top: 10px; font-size: 8pt; color: #888; text-align: center; }
  @media print {
    .pms-invoice { font-size: 9pt; }
    .pms-invoice .pms-disclaimer { border-color: #000; color: #000; background: #f9f9f9; }
  }
</style>

<div class="pms-invoice">

  <!-- Company Header -->
  <div class="header-section">
    <div class="company-name">{{ _company_name }}</div>
    {%- if _cr_number %}
    <div class="company-detail"><strong>CR No:</strong> {{ _cr_number }}</div>
    {%- endif %}
    {%- if _vat_registration_number %}
    <div class="company-detail"><strong>VAT No:</strong> {{ _vat_registration_number }}</div>
    {%- endif %}
    {%- if _company_address %}
    <div class="company-detail">{{ _company_address | replace("\n", ", ") }}</div>
    {%- endif %}
    {%- if _company_phone %}
    <div class="company-detail">Tel: {{ _company_phone }}</div>
    {%- endif %}
  </div>

  <div class="invoice-title">
    {%- if has_pms %}TAX INVOICE{%- else %}TAX INVOICE{%- endif %}
  </div>

  <!-- Invoice Meta -->
  <table class="meta-table">
    <tr>
      <td style="width:50%"><strong>Invoice:</strong> {{ doc.name }}</td>
      <td style="width:50%"><strong>Date:</strong> {{ frappe.format_date(doc.posting_date) }}</td>
    </tr>
    <tr>
      <td><strong>Customer:</strong> {{ doc.customer_name or doc.customer }}</td>
      <td>
        {%- set cust = frappe.get_doc('Customer', doc.customer) -%}
        {%- if cust.tax_id %}<strong>Customer VAT No:</strong> {{ cust.tax_id }}{%- endif %}
      </td>
    </tr>
  </table>

  <!-- Line Items -->
  <table>
    <thead>
      <tr>
        <th style="width:5%">#</th>
        <th style="width:40%">Description</th>
        <th class="text-center" style="width:10%">Qty</th>
        {%- if not has_pms %}
        <th class="text-right" style="width:15%">Unit Price</th>
        <th class="text-right" style="width:15%">VAT (10%)</th>
        {%- else %}
        <th class="text-right" style="width:15%">Price</th>
        {%- endif %}
        <th class="text-right" style="width:15%">Amount ({{ currency }})</th>
      </tr>
    </thead>
    <tbody>
      {%- for item in doc.items %}
      <tr>
        <td class="text-center">{{ loop.index }}</td>
        <td>{{ item.item_name or item.item_code }}{%- if item.description and item.description != item.item_name %}<br><small style="color:#888">{{ item.description | truncate(80) }}</small>{%- endif %}</td>
        <td class="text-center">{{ item.qty | int if item.qty == (item.qty | int) else item.qty }}</td>
        {%- if not has_pms %}
        <td class="text-right">{{ frappe.utils.fmt_money(item.rate, currency=currency) }}</td>
        <td class="text-right">{{ frappe.utils.fmt_money(item.rate * item.qty * 0.1, currency=currency) }}</td>
        <td class="text-right">{{ frappe.utils.fmt_money(item.amount * 1.1, currency=currency) }}</td>
        {%- else %}
        {#- PMS: show only the final price — NO tax breakdown -#}
        <td class="text-right">{{ frappe.utils.fmt_money(item.rate, currency=currency) }}</td>
        <td class="text-right">{{ frappe.utils.fmt_money(item.amount, currency=currency) }}</td>
        {%- endif %}
      </tr>
      {%- endfor %}
    </tbody>
  </table>

  <!-- Totals -->
  <table class="totals-table">
    {%- if has_pms %}
    {#- PMS invoice: single total, NO tax line shown to customer -#}
    <tr class="grand-total">
      <td>Total ({{ currency }})</td>
      <td class="text-right">{{ frappe.utils.fmt_money(doc.grand_total, currency=currency) }}</td>
    </tr>
    {%- else %}
    {#- Standard invoice: show subtotal + VAT + grand total -#}
    <tr>
      <td>Subtotal</td>
      <td class="text-right">{{ frappe.utils.fmt_money(doc.net_total, currency=currency) }}</td>
    </tr>
    <tr>
      <td>VAT (10%)</td>
      <td class="text-right">{{ frappe.utils.fmt_money(doc.total_taxes_and_charges, currency=currency) }}</td>
    </tr>
    {%- if doc.discount_amount %}
    <tr>
      <td>Discount</td>
      <td class="text-right">-{{ frappe.utils.fmt_money(doc.discount_amount, currency=currency) }}</td>
    </tr>
    {%- endif %}
    <tr class="grand-total">
      <td>Grand Total ({{ currency }})</td>
      <td class="text-right">{{ frappe.utils.fmt_money(doc.grand_total, currency=currency) }}</td>
    </tr>
    {%- endif %}
  </table>

  {#- PMS Disclaimer — mandatory for PMS invoices -#}
  {%- if has_pms and pms_disclaimer %}
  <div class="pms-disclaimer">
    {{ pms_disclaimer }}
  </div>
  {%- endif %}

  {#- Payment Info -#}
  {%- if doc.payments and doc.payments | length > 0 %}
  <div style="margin-top:10px; font-size:9pt;">
    <strong>Payment:</strong>
    {%- for p in doc.payments %}
      {{ p.mode_of_payment }}: {{ frappe.utils.fmt_money(p.amount, currency=currency) }}{%- if not loop.last %}, {% endif %}
    {%- endfor %}
  </div>
  {%- endif %}

  <div class="footer-note">
    Thank you for your business.
  </div>

</div>
